"""Shared numbers and paths for the dawn scene's animal pipeline (rigs.py and trace.py).

No bpy import here, so the plain system Python can read it too.
"""
from __future__ import annotations

import os
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[1]

# Generated by trace.py, read by packages/design/src/dawnScene.ts. Never edit it by hand.
SPRITES_TS = REPO / "packages/design/src/dawnSprites.generated.ts"

MASK_PX_PER_M = 300        # silhouette render scale
PATH_UNITS_PER_M = 200     # SVG path units: 1 unit = 5 mm, whole numbers only (small files, still smooth)


def work_dir() -> Path:
    """Rendered masks (scratch, outside the repo)."""
    return Path(os.environ.get("HCM_BG_WORK", Path.home() / ".cache/huntclubmesh/background_work"))
